# ingestion/transaction_simulator.py
# ============================================================
# Simulates M-Pesa transactions being generated by customers.
# In a real company this would be replaced by the actual
# M-Pesa API or internal transaction database connection.
# ============================================================

import random
import uuid
import json
from datetime import datetime

# Customer pool
CUSTOMERS = ['CUST001', 'CUST002', 'CUST003', 'CUST004', 'CUST005']

# Transaction types
TXN_TYPES = ['send', 'receive', 'withdraw', 'paybill', 'buy_goods']

# Locations
LOCATIONS = [
    {'county': 'Nairobi',  'town': 'CBD',       'is_known': True},
    {'county': 'Nairobi',  'town': 'Westlands', 'is_known': True},
    {'county': 'Mombasa',  'town': 'Nyali',     'is_known': True},
    {'county': 'Kisumu',   'town': 'Milimani',  'is_known': True},
    {'county': 'Unknown',  'town': 'Unknown',   'is_known': False},   # suspicious
    {'county': 'Overseas', 'town': 'Overseas',  'is_known': False},   # very suspicious
]

# Device types
DEVICE_TYPES = ['android', 'ios', 'ussd']


def generate_normal_transaction():
    """Generate a normal, legitimate transaction."""
    customer = random.choice(CUSTOMERS[:4])  # known customers
    location = random.choice(LOCATIONS[:4])  # known locations
    return {
        'transaction_id':     str(uuid.uuid4()),
        'customer_id':        customer,
        'amount':             round(random.uniform(50, 10000), 2),
        'txn_type':           random.choice(TXN_TYPES),
        'receiver_id':        f"RECV{random.randint(1000,9999)}",
        'county':             location['county'],
        'town':               location['town'],
        'is_known_location':  location['is_known'],
        'device_id':          f"DEVICE_{customer}_001",  # known device
        'is_new_device':      False,
        'txn_count_last_1hr': random.randint(0, 3),
        'txn_count_last_24hr':random.randint(0, 15),
        'days_since_last_txn':random.randint(0, 10),
        'timestamp':          datetime.now().isoformat(),
        'is_night':           False,
    }


def generate_fraudulent_transaction():
    """Generate a suspicious/fraudulent transaction."""
    fraud_type = random.choice([
        'large_amount',
        'velocity',
        'new_device',
        'unknown_location',
        'dormant_account',
        'night_large',
    ])

    txn = generate_normal_transaction()  # start with base transaction

    if fraud_type == 'large_amount':
        txn['amount'] = round(random.uniform(150000, 500000), 2)

    elif fraud_type == 'velocity':
        txn['txn_count_last_1hr']  = random.randint(15, 30)
        txn['txn_count_last_24hr'] = random.randint(60, 100)

    elif fraud_type == 'new_device':
        txn['device_id']     = f"DEVICE_UNKNOWN_{uuid.uuid4().hex[:8]}"
        txn['is_new_device'] = True

    elif fraud_type == 'unknown_location':
        loc = random.choice(LOCATIONS[4:])  # overseas or unknown
        txn['county']            = loc['county']
        txn['town']              = loc['town']
        txn['is_known_location'] = loc['is_known']

    elif fraud_type == 'dormant_account':
        txn['customer_id']         = 'CUST005'   # new/dormant customer
        txn['days_since_last_txn'] = random.randint(100, 365)
        txn['amount']              = round(random.uniform(80000, 200000), 2)

    elif fraud_type == 'night_large':
        txn['amount']   = round(random.uniform(60000, 200000), 2)
        txn['is_night'] = True

    return txn


def get_batch_of_transactions(batch_size=10):
    """
    Returns a batch of mixed transactions.
    90% normal, 10% fraudulent — realistic ratio.
    In production this calls the real M-Pesa API.
    """
    transactions = []
    for _ in range(batch_size):
        if random.random() < 0.10:   # 10% chance of fraud
            txn = generate_fraudulent_transaction()
        else:
            txn = generate_normal_transaction()
        transactions.append(txn)
    return transactions


if __name__ == '__main__':
    # Quick test — print 5 sample transactions
    print("=== Sample Transactions ===\n")
    for txn in get_batch_of_transactions(5):
        print(json.dumps(txn, indent=2))
        print()
